function hasPathSum(root: TreeNode | null, targetSum: number): boolean {
  // В пустом дереве путей нет
  if (root === null) {
    return false;
  }

  // Сколько ещё нужно набрать ниже текущего узла
  const rest = targetSum - root.val;

  // Лист: путь закончился, проверяем, набрали ли ровно targetSum
  if (root.left === null && root.right === null) {
    return rest === 0;
  }

  // Иначе ищем подходящий путь в любом из поддеревьев
  return hasPathSum(root.left, rest) || hasPathSum(root.right, rest);
}

// Время: O(n) — в худшем случае посещаем все узлы
// Память: O(h) — стек рекурсии
